  'st.header_title': 'Authenticatie via HTTP-header',
  'st.header_intro': 'Alleen gebruikt als de authenticatie “HTTP-header” is. Een reverse proxy of single-sign-on-gateway meldt gebruikers aan en geeft de gebruikersnaam door in een header; pgkiln vertrouwt die alleen vanaf de proxy-adressen in {env}',
