  'st.header_auto': 'Accounts automatisch aanmaken',
  'st.header_auto_help': 'Een onbekende gebruikersnaam krijgt een nieuw account met toegang tot deze applicatie. Anders moet het account bestaan en toegang hebben.',
  'st.db_title': 'Databaseaccounts',
  'st.db_intro': 'Alleen gebruikt als de authenticatie “Databaseaccounts” is. Gebruikers melden zich aan met een PostgreSQL-loginrol en het wachtwoord daarvan, gecontroleerd met een korte verbinding met deze database als die rol. Superusers en de eigen rollen van pgkiln worden altijd geweigerd; zonder een van beide velden kan niemand aanmelden.',
  'st.db_roles': 'Toegestane rollen',
