  'st.session_group_ph': 'leeg: niet gedeeld',
  'st.session_group_help': 'Applicaties met dezelfde groep (en de gebruikersdirectory als authenticatie) delen een aanmelding: na het aanmelden bij de ene openen de andere zonder nieuwe aanmelding, elk met een eigen toegangscontrole en rollen; afmelden bij de ene meldt af bij alle (APEX: session sharing). Kleine letters, cijfers en _.',
