  'rs.not_in_query': 'niet in de query',
  'rpt.report_settings': 'Rapportinstellingen',
  'rpt.save_report_settings': 'Rapportinstellingen opslaan',
  'rs.no_position_alert': 'Het rapport heeft geen kolommen `lat`/`lng` of `location`, dus het kaartgebied kan het niet filteren.',
  'rs.facets_help': 'Selectievakjes tonen de meest voorkomende waarden (met Uitsluiten filteren gebruikers ze juist weg). Bereiken en Van/tot hebben een getal- of datumkolom nodig: bereiken zijn `from..to = label` gescheiden door `;`, een open einde leeg gelaten (`..1000`, `2020-01-01..`); een bereik bevat zijn begin, niet zijn einde. Een sterrenbeoordeling biedt "4 sterren en meer" enzovoort (tot 5; `"max"` in de JSON wijzigt dat).',
  'rs.facets_help_chart': 'Grafiek: een staaf- of cirkeldiagram van de aantallen onder het facet (ingeklapt); een staaf of segment filtert op zijn waarde.',
  'rs.calendar_help': 'De query geeft `start_date`, `title` en optioneel `end_date` terug (datums voor gebeurtenissen van een hele dag, tijdstempels voor gebeurtenissen met een tijd).',
  'rs.chart_help': 'De eerste kolom is het label; elke volgende numerieke kolom is een reeks (maximaal 8). Een Gantt-diagram leest `label, start, end` (datums of tijdstempels; een leeg einde is een mijlpaal) en optionele kolommen `progress` (0 tot 100), `task_id` en `depends_on` (de ids waarop een taak wacht, bijv. `3,4`).',
  'rs.map_help': 'Elke rij is een markering op `lat`, `lng` (of `location` als "lat,lng"), met `title` en `body` in de pop-up; een kolom `geojson` tekent lijnen en vlakken (met PostGIS geïnstalleerd werkt ook een kolom `geometry` of `geography` in WGS 84). Een heatmap weegt elke plaats met een kolom `weight`.',
  'rs.tree_help': 'De query geeft `id`, `parent_id` en `label` terug (en optioneel `icon`); rijen waarvan de ouder niet in het resultaat staat, zijn de wortels.',
