  'rm.chk.disabled': 'Uitgeschakeld: elke handler antwoordt 404',
  'rm.chk.privilege': 'Privilege: aanroepers hebben de rol {roles} nodig',
  'rm.chk.no_privilege': 'Geen privilegerollen: elk geldig token van de applicatie (handlers kunnen rollen toevoegen)',
  'rm.response_as': '{request} als {as}',
  'rm.try_intro': 'Stuurt het verzoek naar het echte endpoint: een PUT, POST of DELETE wijzigt gegevens. {as} een account geeft er een kortlevend token voor uit, zoals App › REST API doet; zonder zie je wat een aanroeper zonder token krijgt.',
  'rm.intro': 'Modules van RESTful Services: een module is een basispad van een applicatie, de templates zijn URI\'s met `:parameters`, en elk template heeft handlers per methode met hun bron: een collectiequery, één rij, SQL, een PL/pgSQL-blok of een mediabron. Handlers draaien als de databaserol van de applicatie met de aanroeper als `meta.app_user()`, dus haar rechten en row level security gelden; parameters worden gebonden, nooit in de SQL geplakt. Elke module heeft een OpenAPI-document. Modules horen bij hun applicatie: ze reizen mee met haar export (ook in Gedeelde componenten › RESTful Services).',
  'rm.source_help': 'Binds, in hoofdletters: padparameters ({params}), queryparameters en velden van de JSON-body; `:BODY` is de hele body; `:APP_USER` is de aanroeper. Waarden worden gebonden, nooit in de SQL geplakt. PL/pgSQL: een blok (`declare … begin … end`, of opdrachten) dat antwoordt met `perform meta.rest_reply(jsonb_build_object(…), 201)`. Media: een query die `content_type`, `content` en optioneel `filename` teruggeeft.',
  'rm.params_help': 'Eén per regel: `name query|body [{types}] [required] [description]`. Ze komen in het OpenAPI-document en het formulier Uitproberen; ontbreekt een verplichte, dan is het antwoord 400.',
  'rm.e.params_line': 'Parameters, regel {n}: schrijf "name query" of "name body", dan optioneel een type ({types}), "required" en een beschrijving.',
  'rm.e.choose_app': 'Kies een applicatie van deze werkruimte.',
