  'agt.intro': 'Een agent antwoordt in een AI-assistentregio en handelt alleen via de tools die je hem geeft: SQL-query\'s (alleen-lezen, als de databaserol van de applicatie, dus row level security geldt), PL/pgSQL-functies, REST-gegevensbronnen, JavaScript-acties in de browser en links naar pagina\'s (pgkiln bouwt de URL en de controlesom, alleen voor pagina\'s die de gebruiker mag openen). Een Retrieve-tool geeft de agent de rijen van een zoekconfiguratie die qua betekenis bij een tekst passen (RAG), opnieuw als de rol van de applicatie. Wat gebruikers typen en de resultaten van de tools gaan naar de AI-dienst van de agent. {usage} toont elke toolaanroep.',
